#!/usr/bin/env bash
# CarryBee QA fixes. Run from your repo root:  bash apply-qa-fixes.sh
# Each file is written only if its current content matches the version these fixes were built on.
# If a file has other changes, it is skipped and listed at the end (nothing is overwritten).
set -u
cd "${1:-.}" || exit 1
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || { echo "Not a git repo here."; exit 1; }
applied=0; skipped=0; already=0
apply_file() {
  local path="$1" base_hash="$2" new_b64="$3" tmp
  tmp=$(mktemp)
  printf '%s' "$new_b64" | base64 -d > "$tmp" || { echo "FAIL decode $path"; rm -f "$tmp"; skipped=$((skipped+1)); return; }
  local new_hash; new_hash=$(git hash-object "$tmp")
  if [ -f "$path" ]; then
    local cur; cur=$(git hash-object "$path")
    if [ "$cur" = "$new_hash" ]; then echo "already applied: $path"; already=$((already+1)); rm -f "$tmp"; return; fi
    if [ "$cur" != "$base_hash" ]; then echo "SKIPPED (differs from expected base, not overwritten): $path"; skipped=$((skipped+1)); rm -f "$tmp"; return; fi
  else
    echo "SKIPPED (missing): $path"; skipped=$((skipped+1)); rm -f "$tmp"; return
  fi
  mv "$tmp" "$path" && echo "updated: $path" && applied=$((applied+1))
}
apply_file 'next.config.js' 'e0f9c91a62ee4aecf85dda0e37e6e266fee4d04f' ''
apply_file 'middleware.js' '3d9988510dce01e0761198cc7ed58189bc689f87' ''
apply_file 'components/AppHeader.js' 'abb17358d6a5af2ae206466051dcfab77a1a0237' ''
apply_file 'app/manifest.js' '774cf29691ee4bb2afe467e064ef17767d2c258e' ''
apply_file 'app/api/masters/route.js' '0749a2e46f86a025e683582a5506251d00b72cc6' ''
apply_file 'app/cw-live.css' '734e7a6bd83e6dc9bf4d33ca8723ba896648a505' ''
apply_file 'lib/sheets.js' 'faf143c8bdb08c0494b6adc15a999f82146e8304' ''
apply_file 'tests/sheetColumns.test.mjs' 'e70ad3e66755a46509dec6111009683648100e72' ''
echo
echo "updated: $applied   already applied: $already   skipped: $skipped"
if [ "$skipped" -eq 0 ]; then
  echo "Next: run the checks, then commit:"
  echo "  node --test tests/*.test.mjs"
  echo "  git add next.config.js middleware.js components/AppHeader.js app/manifest.js app/api/masters/route.js app/cw-live.css lib/sheets.js tests/sheetColumns.test.mjs"
  echo "  git commit -m \"QA fixes: security headers, logo access, sign-in touch targets, masters read scope, sheet test\""
  echo "  git push origin main"
else
  echo "Some files were skipped. Do not commit yet. Send the output above back to me."
fi
